
from datetime import datetime, timezone

from sqlalchemy import CheckConstraint

from app.extensions import db


# Represents a notification generated by the FloodShield backend.
class Notification(db.Model):

    __tablename__ = "notifications"

    # Enforce notification integrity at the database level.
    __table_args__ = (
        CheckConstraint(
            "length(trim(title)) > 0",
            name="check_notification_title"
        ),
        CheckConstraint(
            "length(trim(message)) > 0",
            name="check_notification_message"
        ),
        CheckConstraint(
            "length(trim(notification_type)) > 0",
            name="check_notification_type"
        ),
        CheckConstraint(
            "deduplication_key IS NULL OR "
            "(length(trim(deduplication_key)) > 0 "
            "AND length(deduplication_key) <= 100)",
            name="check_notification_deduplication_key"
        ),
        CheckConstraint(
            "risk_level IS NULL OR "
            "risk_level IN ('low', 'moderate', 'high', 'severe')",
            name="check_notification_risk_level"
        ),
        CheckConstraint(
            "latitude IS NULL OR "
            "(latitude >= -90 AND latitude <= 90)",
            name="check_notification_latitude"
        ),
        CheckConstraint(
            "longitude IS NULL OR "
            "(longitude >= -180 AND longitude <= 180)",
            name="check_notification_longitude"
        ),
        CheckConstraint(
            "delivery_status IN "
            "('pending', 'no_devices', 'sent', 'partial', 'failed')",
            name="check_notification_delivery_status"
        ),
    )

    id = db.Column(db.Integer, primary_key=True)

    # User who should receive this notification.
    user_id = db.Column(
        db.Integer,
        db.ForeignKey("users.id"),
        nullable=False,
        index=True
    )

    # Notification title and message.
    title = db.Column(db.String(150), nullable=False)
    message = db.Column(db.Text, nullable=False)

    # Type of notification, such as flood_alert or system_alert.
    notification_type = db.Column(
        db.String(50),
        nullable=False,
        default="flood_alert"
    )

    deduplication_key = db.Column(
        db.String(100),
        nullable=True,
        index=True
    )

    # Risk level associated with the alert.
    risk_level = db.Column(db.String(30), nullable=True)

    # Optional coordinates associated with the alert.
    latitude = db.Column(db.Float, nullable=True)
    longitude = db.Column(db.Float, nullable=True)

    # Whether the user has read the notification.
    is_read = db.Column(
        db.Boolean,
        nullable=False,
        default=False
    )

    # Firebase delivery status.
    delivery_status = db.Column(
        db.String(30),
        nullable=False,
        default="pending"
    )

    created_at = db.Column(
        db.DateTime(timezone=True),
        default=lambda: datetime.now(timezone.utc),
        nullable=False
    )

    read_at = db.Column(
        db.DateTime(timezone=True),
        nullable=True
    )

    def __repr__(self):
        return f"<Notification {self.id}: {self.title}>"
